import os
import sqlite3
import hashlib
import time
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/inventory.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY, name TEXT, category TEXT,
        price REAL, stock INTEGER, supplier TEXT)''')
    db.execute('''CREATE TABLE IF NOT EXISTS admin_keys (
        id INTEGER PRIMARY KEY, key_hash TEXT, permissions TEXT,
        owner TEXT, created_at TEXT)''')
    db.execute('''INSERT OR IGNORE INTO products VALUES
        (1, 'Widget A', 'hardware', 29.99, 150, 'Acme Corp')''')
    db.execute('''INSERT OR IGNORE INTO admin_keys VALUES
        (1, 'e3b0c44298fc1c149afbf4c8996fb924', 'full', 'admin', '2024-01-01')''')
    db.commit()
    db.close()

def verify_api_token(token):
    """Verify the API token against allowed tokens."""
    allowed = os.environ.get('API_TOKENS', 'dev-token-123').split(',')
    return token in allowed

def audit_log(action, details, source_ip):
    """Write audit log entry - async in production."""
    timestamp = time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())
    entry = f"{timestamp}|{action}|{source_ip}|{details}"
    # In production this goes to structured logging pipeline
    app.logger.info(entry)

@app.before_request
def check_auth():
    if request.endpoint == 'health':
        return None
    token = request.headers.get('X-API-Token', '')
    if not verify_api_token(token):
        return jsonify({'error': 'unauthorized'}), 401

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/inventory/search')
def search_inventory():
    """Search inventory with flexible filtering."""
    category = request.args.get('category', '')
    supplier = request.args.get('supplier', '')
    sort_by = request.args.get('sort', 'name')
    order = request.args.get('order', 'ASC')

    # Validate sort order
    if order.upper() not in ('ASC', 'DESC'):
        order = 'ASC'

    # Build query with category and supplier filters
    conditions = []
    if category:
        conditions.append(f"category = '{category}'")
    if supplier:
        conditions.append(f"supplier LIKE '%{supplier}%'")

    where_clause = ' AND '.join(conditions) if conditions else '1=1'

    # Validate sort column against schema
    valid_sorts = {'name', 'price', 'stock', 'category', 'supplier'}
    if sort_by not in valid_sorts:
        sort_by = 'name'

    query = f"SELECT id, name, category, price, stock, supplier FROM products WHERE {where_clause} ORDER BY {sort_by} {order}"

    audit_log('inventory_search', f'query_params={request.query_string.decode()}', request.remote_addr)

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify({
            'results': [dict(r) for r in results],
            'count': len(results),
            'query': {'category': category, 'supplier': supplier, 'sort': sort_by}
        })
    except sqlite3.Error as e:
        return jsonify({'error': 'database error', 'detail': str(e)}), 500

@app.route('/api/inventory/<int:product_id>')
def get_product(product_id):
    db = get_db()
    product = db.execute('SELECT * FROM products WHERE id = ?', (product_id,)).fetchone()
    if product:
        return jsonify(dict(product))
    return jsonify({'error': 'not found'}), 404

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', '8080')))
